import {
  deleteHabit,
  incrementCompletionTimes,
  decrementCompletionTimes,
} from "../functions";

function CreateAHabit({
  setCurrentHabit,
  isNoteOpen,
  setIsNoteOpen,
  habit,
  forEditing,
  setForEditing,
  setEditId,
  setIsItOpened,
  habits,
  setAHabit,
}) {
  //  all HTML code is generated by claude. Not gonna waste time writing HTML code in a react training project.

  const note = habit["note"];
  const name = habit["name"];
  const id = habit["id"];
  const timesPerDay = habit["timesPerDay"];
  const timesOfCompletion = habit["timesOfCompletion"];
  const done = habit["done"];

  return (
    <>
      <div
        className="relative bg-neutral-800 border border-neutral-700 rounded-xl p-4 max-w-60 w-full"
        data-id={id}
      >
        <span className="text-xl">💧</span>

        <div className="absolute top-4 right-4 flex gap-3 text-neutral-400 ">
          {note !== "" && (
            <button
              aria-label="View note"
              className="cursor-pointer"
              title={note}
              onClick={() => {
                setCurrentHabit(habit);
                setIsNoteOpen(true);
              }}
            >
              📝
            </button>
          )}
          <button
            aria-label="Edit habit"
            onClick={(event) => {
              const target = event.target;
              const id: string = target.parentElement.parentElement.dataset.id;

              setIsItOpened(true);
              setForEditing(true);
              setEditId(id);
            }}
            className="cursor-pointer"
          >
            ✏️
          </button>
          <button
            aria-label="Delete habit"
            className="cursor-pointer"
            onClick={(e) => {
              deleteHabit(e, setAHabit, habits);
            }}
          >
            🗑️
          </button>
        </div>

        {done === true ? (
          <>
            <div className="text-sm font-medium text-neutral-500 line-through mt-2">
              {name}
            </div>
            <p className="text-xs text-green-500 mt-1 mb-3">
              ✓ Completed today
            </p>

            <div className="flex gap-2">
              <button
                disabled
                className="flex-1 flex items-center px-3 text-sm border border-green-700 bg-green-950/40 rounded-lg py-1.5 text-green-500 cursor-default transition-colors duration-700 ease-in-out"
              >
                <span className="flex-1 text-center">✓ Done</span>
              </button>

              <button
                onClick={() => {
                  decrementCompletionTimes(habits, id, setAHabit);
                }}
                aria-label="Undo one"
                className="w-9 flex items-center justify-center border border-neutral-600 rounded-lg text-neutral-300 cursor-pointer"
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="16"
                  height="16"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  stroke-width="2"
                  stroke-linecap="round"
                  stroke-linejoin="round"
                >
                  <path d="M9 14l-4 -4l4 -4" />
                  <path d="M5 10h11a4 4 0 1 1 0 8h-1" />
                </svg>
              </button>
            </div>
          </>
        ) : (
          <>
            <div className="text-sm font-medium text-neutral-100 mt-2 transition-colors duration-700 ease-in-out">
              {name}
            </div>
            <p className="text-xs text-neutral-400 mt-1 mb-3">12 day streak</p>
            <div className="flex gap-2">
              <button
                onClick={() => {
                  incrementCompletionTimes(habits, id, setAHabit);
                }}
                className="flex-1 flex items-center px-3 text-sm border border-neutral-600 rounded-lg py-1.5 text-neutral-300 cursor-pointer transition-colors duration-700 ease-in-out active:scale-95"
              >
                <span className="flex-1 text-center text-[14.5px]">
                  Mark done
                </span>
                {timesPerDay > 1 && (
                  <span className="text-sm text-neutral-500">
                    {timesOfCompletion}/{timesPerDay}
                  </span>
                )}
              </button>
              <button
                aria-label="Undo one"
                onClick={() => {
                  decrementCompletionTimes(habits, id, setAHabit);
                }}
                className={`${timesOfCompletion < 1 && "hidden"} w-9 flex items-center justify-center border border-neutral-600 rounded-lg text-neutral-300 cursor-pointer`}
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="16"
                  height="16"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  stroke-width="2"
                  stroke-linecap="round"
                  stroke-linejoin="round"
                >
                  <path d="M9 14l-4 -4l4 -4" />
                  <path d="M5 10h11a4 4 0 1 1 0 8h-1" />
                </svg>
              </button>
            </div>
          </>
        )}
      </div>
    </>
  );
}
export { CreateAHabit };
